                  {...(item.id === 'chatThread.message.menu.reply'
                    ? bindTap('chatThread.message.thread.open', {
                        params: {
                          username,
                          messageId: getChatMessageOccurrenceId(longPressMenu),
                        },
                        beforeTrigger: () => {
                          // Close overlays before navigating.
                          setConfirmDelete(null);
                          setLongPressMenu(null);
                        },
                      })
                    : bindTap(
                        { kind: 'action', id: item.id },
                        {
                          params: {
                            username,
                            messageId: getChatMessageOccurrenceId(longPressMenu),
                          },
                          onTrigger: item.onTrigger,
                        },
                      ))}
                  className="w-full flex items-center gap-4 px-6 py-4 text-left active:bg-gray-50"
                >
                  <div className="w-7 h-7 flex items-center justify-center text-gray-800">{item.icon}</div>
                  <div className="text-[18px] text-app-text">{item.label}</div>
                </button>
              ))}
              <div className="h-3" />
            </div>
          </div>
        </div>
      )}

      {/* Delete confirm dialog (shown above long-press menu) */}
      {confirmDelete && (
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Reply"
            className="flex-1 h-11 px-4 rounded-full bg-gray-100 outline-none text-[15px] text-app-text placeholder-gray-500"
          />
          <button
            type="button"
            aria-label="Send reply"
            onPointerDown={(e) => e.preventDefault()}
            {...bindTap(
              { kind: 'action', id: 'chatThread.reply.submit' },
              {
                params: { username, messageId: messageOccurrenceId, body: draft },
                onTrigger: submit,
              },
            )}
            className={`w-11 h-11 rounded-full flex items-center justify-center ${
              canSend ? 'text-[#0045AC]' : 'text-gray-300'
            }`}
          >
            <IcSend className="w-6 h-6" strokeWidth={2} />
          </button>
        </div>
      </div>
